import Foundation

#if canImport(Metal)
@preconcurrency import Metal

/// Precompiled `.metallib` loader, freshness verifier, and catalog for built-in Metal shaders (`render/metallib.rs`).
///
/// Precompiled libraries are generated by `scripts/precompile-metal-shaders.sh` into
/// `Resources/Metal/{macos,ios_sim,ios}/*.metallib` alongside `Resources/Metal/manifest.tsv`
/// (FNV-1a 64-bit hashes of each MSL source string). If a `.metallib` is absent, for a different
/// platform, stale relative to the runtime MSL string, or disabled via `RUNE_DISABLE_METALLIB=1`,
/// callers fall back seamlessly to `device.makeLibrary(source:options:)`.
public enum PrecompiledMetallib {
    public struct ShaderEntry: Sendable {
        public let name: String
        public let source: String
        public let requiredFunction: String

        public init(name: String, source: String, requiredFunction: String) {
            self.name = name
            self.source = source
            self.requiredFunction = requiredFunction
        }
    }

    private final class State: @unchecked Sendable {
        let lock = NSLock()
        var forceEnabled: Bool?
        var loadCount: Int = 0
        var manifestCache: [String: [String: UInt64]] = [:]
    }

    private static let state = State()

    /// SwiftPM resource bundle for `Rune`.
    public static var runeResourceBundle: Bundle { Bundle.module }

    /// Subdirectory inside `Resources/Metal` matching the current Apple SDK target.
    public static var platformSubdirectory: String {
        #if os(macOS)
        return "macos"
        #elseif targetEnvironment(simulator)
        return "ios_sim"
        #else
        return "ios"
        #endif
    }

    /// Deterministic FNV-1a 64-bit hash of a shader MSL string.
    public static func fnv64(_ string: String) -> UInt64 {
        var hash: UInt64 = 0xcbf2_9ce4_8422_2325
        for byte in string.utf8 {
            hash ^= UInt64(byte)
            hash &*= 0x0000_0100_0000_01b3
        }
        return hash
    }

    /// Formats `fnv64` as lowercase 16-digit hex.
    public static func fnv64Hex(_ string: String) -> String {
        let h = fnv64(string)
        let s = String(h, radix: 16, uppercase: false)
        return s.count < 16 ? String(repeating: "0", count: 16 - s.count) + s : s
    }

    /// Number of times a precompiled `.metallib` was loaded during this process.
    public static var precompiledLoadCount: Int {
        state.lock.lock()
        defer { state.lock.unlock() }
        return state.loadCount
    }

    /// Test helper: overrides `RUNE_DISABLE_METALLIB` when non-nil.
    public static func setForceEnabledForTesting(_ enabled: Bool?) {
        state.lock.lock()
        state.forceEnabled = enabled
        state.lock.unlock()
    }

    /// Test helper: resets `precompiledLoadCount` to zero.
    public static func resetLoadCountForTesting() {
        state.lock.lock()
        state.loadCount = 0
        state.lock.unlock()
    }

    /// Whether precompiled `.metallib` loading is currently active.
    public static var isEnabled: Bool {
        state.lock.lock()
        let forced = state.forceEnabled
        state.lock.unlock()
        if let forced { return forced }
        if let raw = ProcessInfo.processInfo.environment["RUNE_DISABLE_METALLIB"]?.lowercased() {
            if raw == "1" || raw == "true" || raw == "yes" {
                return false
            }
        }
        return true
    }

    /// All built-in Metal shaders owned by the `Rune` module.
    public static var builtinEntries: [ShaderEntry] {
        [
            ShaderEntry(name: "shader", source: RenderShaders.shaderMSL, requiredFunction: "vs_springs"),
            ShaderEntry(name: "layer_blur", source: RenderShaders.layerBlurMSL, requiredFunction: "layer_blur_vs"),
            ShaderEntry(name: "backdrop_blur", source: RenderShaders.backdropBlurMSL, requiredFunction: "backdrop_blur_vs"),
            ShaderEntry(name: "backdrop_composite", source: RenderShaders.backdropCompositeMSL, requiredFunction: "backdrop_composite_vs"),
            ShaderEntry(name: "video", source: SurfaceRenderer.mslSource, requiredFunction: "video_vs"),
            ShaderEntry(name: "legacy_rune", source: MetalRenderer.mslSource, requiredFunction: "rune_vertex"),
        ]
    }

    /// Attempts to load a precompiled `.metallib` for `name` and verify freshness against `source`.
    public static func load(
        named name: String,
        source: String,
        requiredFunction: String,
        bundle: Bundle? = nil,
        on device: MTLDevice
    ) -> MTLLibrary? {
        guard isEnabled else { return nil }

        let expectedHash = fnv64(source)
        let candidateBundles = uniqueBundles([
            bundle,
            Bundle.module,
            Bundle.main,
            Bundle(for: LayerBlurPipeline.self),
        ])

        for candidate in candidateBundles {
            if let manifest = loadManifest(in: candidate), let recordedHash = manifest[name], recordedHash != expectedHash {
                // Source string changed after `.metallib` was precompiled; fall back to runtime MSL compilation.
                continue
            }
            if let url = locateMetallibURL(named: name, in: candidate),
               let library = try? device.makeLibrary(URL: url),
               library.functionNames.contains(requiredFunction) {
                state.lock.lock()
                state.loadCount += 1
                state.lock.unlock()
                return library
            }
        }

        if let def = device.makeDefaultLibrary(), def.functionNames.contains(requiredFunction) {
            state.lock.lock()
            state.loadCount += 1
            state.lock.unlock()
            return def
        }
        return nil
    }

    /// Loads either a fresh precompiled `.metallib` (when `allowPrecompiled && isEnabled`) or compiles `source` at runtime,
    /// returning `(library, usedPrecompiled)` without mutating global cache or enable flags.
    public static func loadLibraryWithOrigin(
        named name: String,
        source: String,
        requiredFunction: String,
        bundle: Bundle? = nil,
        allowPrecompiled: Bool = true,
        on device: MTLDevice
    ) throws -> (library: MTLLibrary, usedPrecompiled: Bool) {
        if allowPrecompiled,
           let precompiled = load(
               named: name,
               source: source,
               requiredFunction: requiredFunction,
               bundle: bundle,
               on: device
           ) {
            return (precompiled, true)
        }
        let compiled = try device.makeLibrary(source: source, options: nil)
        return (compiled, false)
    }

    /// Parses `Metal/manifest.tsv` (`<name>\t<16-char hex fnv64>`) if present in `bundle`.
    public static func loadManifest(in bundle: Bundle) -> [String: UInt64]? {
        let cacheKey = bundle.bundlePath
        state.lock.lock()
        if let cached = state.manifestCache[cacheKey] {
            state.lock.unlock()
            return cached
        }
        state.lock.unlock()

        let url = bundle.url(forResource: "manifest", withExtension: "tsv", subdirectory: "Metal")
            ?? bundle.url(forResource: "manifest", withExtension: "tsv")
            ?? bundle.resourceURL?.appendingPathComponent("Metal/manifest.tsv")
        guard let url,
              FileManager.default.fileExists(atPath: url.path),
              let text = try? String(contentsOf: url, encoding: .utf8) else {
            return nil
        }

        var map: [String: UInt64] = [:]
        for line in text.split(whereSeparator: \.isNewline) {
            let trimmed = line.trimmingCharacters(in: .whitespaces)
            if trimmed.isEmpty || trimmed.hasPrefix("#") { continue }
            let parts = trimmed.split(separator: "\t", omittingEmptySubsequences: true)
            if parts.count >= 2, let value = UInt64(parts[1], radix: 16) {
                map[String(parts[0])] = value
            }
        }

        state.lock.lock()
        state.manifestCache[cacheKey] = map
        state.lock.unlock()
        return map
    }

    /// Writes `entries` (`<name>.metal` + `manifest.tsv`) into `directory` for offline `.metallib` compilation.
    public static func dumpShaders(_ entries: [ShaderEntry], to directory: URL) throws {
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        var manifestLines: [String] = ["# name\tfnv64"]
        for entry in entries {
            let metalURL = directory.appendingPathComponent("\(entry.name).metal")
            try entry.source.write(to: metalURL, atomically: true, encoding: .utf8)
            manifestLines.append("\(entry.name)\t\(fnv64Hex(entry.source))")
        }
        let manifestURL = directory.appendingPathComponent("manifest.tsv")
        try (manifestLines.joined(separator: "\n") + "\n").write(to: manifestURL, atomically: true, encoding: .utf8)
    }

    private static func locateMetallibURL(named name: String, in bundle: Bundle) -> URL? {
        let sub = platformSubdirectory
        if let url = bundle.url(forResource: name, withExtension: "metallib", subdirectory: "Metal/\(sub)") {
            return url
        }
        if let direct = bundle.resourceURL?.appendingPathComponent("Metal/\(sub)/\(name).metallib"),
           FileManager.default.fileExists(atPath: direct.path) {
            return direct
        }
        // Only fall back to flat bundle lookup on macOS where un-prefixed resources may live at bundle root.
        #if os(macOS)
        if let url = bundle.url(forResource: name, withExtension: "metallib") {
            return url
        }
        #endif
        return nil
    }

    private static func uniqueBundles(_ bundles: [Bundle?]) -> [Bundle] {
        var seen = Set<String>()
        var result: [Bundle] = []
        for b in bundles {
            guard let b else { continue }
            if seen.insert(b.bundlePath).inserted {
                result.append(b)
            }
        }
        return result
    }
}
#endif
